import{_ as e,o as t,c as p,a5 as n}from"./chunks/framework.DJo0M80U.js";const _=JSON.parse('{"title":"报错","description":"","frontmatter":{"title":"报错","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","构建运维","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/报错.md","filePath":"posts/java快速入门/第七部分：构建与运维/01-Maven/报错.md"}'),s={name:"posts/java快速入门/第七部分：构建与运维/01-Maven/报错.md"};function r(o,a,i,l,c,m){return t(),p("div",null,[...a[0]||(a[0]=[n('<div><p>maven package命名报错：You have to use a classifier to attach supplemental artifacts to the project inste</p><p>AmNan_Liu</p><p>于 2020-09-18 10:40:47 发布</p><p>4891 收藏 文章标签： java maven 版权 本地项目pom.xml文件添加了maven-jar-plugin插件，如下图! 然后执行maven package命名，结果BUILD FAILURE 具体报错信息如下：Failed to execute goal org.apache.maven.plugins:maven-jar-plugin:3.2.0:jar (make-a-jar) on project common: You have to use a classifier to attach supplemental artifacts to the project instead of replacing them. -&gt; [Help 1]</p><p>然后pom文件中加入一行代码 再次执行maven package，BUILD SUCCESS</p><p>分析原因是因为：如果在plugin中添加maven-jar-plugin插件之后，maven会运行两次maven-jar-plugin插件，第一次运行是打包当前工程的jar，第二次运行是执行在plugin中设置的jar，这样的话会生成两个jar包，这里就要用到classifier这个属性了。classifier是用来标识不同的jar包的名称的一个分类符，这个属性的值会添加到工程jar包的名称后面。 ———————————————— 版权声明：本文为CSDN博主「AmNan_Liu」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/liu98k/article/details/108660345" target="_blank" rel="noreferrer">https://blog.csdn.net/liu98k/article/details/108660345</a></p><p>zsh: command not found: mvn</p><p>梦其不可梦</p><p>于 2021-05-31 21:28:31 发布</p><p>11904 收藏 15 分类专栏： Java 文章标签： java 版权</p><p>华为云开发者联盟 该内容已被华为云开发者联盟社区收录，社区免费抽大奖🎉，赢华为平板、Switch等好礼！ 加入社区</p><p>Java 专栏收录该内容 4 篇文章0 订阅 订阅专栏 一、现象： 运行mvn有关命令，报错“zsh: command not found: mvn”</p><p>二、原因 环境变量的配置文件没有生效。</p><p>三、解决方法 法一 使配置文件生效，使用如下命令。</p><p>source ~/.bash_profile 1 法二 现象：法一只能解决一次问题，因为重新打开终端，执行mvn相关命令，依然报错“zsh: command not found: mvn”，需要再执行source ~/.bash_profile才可以。 原因：zsh的配置文件没有加载~/.bash_profile的配置项。 解决方法：在zsh的配置文件中添加source ~/.bash_profile配置项的内容</p><p>vim ~/.zshrc 1 添加如下内容：</p><p>source ~/.bash_profile 1</p><p>———————————————— 版权声明：本文为CSDN博主「梦其不可梦」的原创文章，遵循CC 4.0 BY-SA版权协议，转载请附上原文出处链接及本声明。 原文链接：<a href="https://blog.csdn.net/weixin_43248785/article/details/117430250" target="_blank" rel="noreferrer">https://blog.csdn.net/weixin_43248785/article/details/117430250</a></p></div>',1)])])}const d=e(s,[["render",r]]);export{_ as __pageData,d as default};
